handlers:
{"@click": "
  const row = document.getElementById('filters-form');
  if (!row) return;
  row.classList.toggle('max-lg:hidden');
  row.scrollIntoView({ behavior: 'smooth', block: 'start' });
"}

{"@change": "
          const s = document.getElementById('core-filters-per-page-input');
          const p = document.getElementById('core-filters-page-input');
          if (p) p.value = '1';
          if (s) { s.value = $event.target.value; s.dispatchEvent(new Event('change', { bubbles: true })) }
        "}

{"@change": "
            const s = document.getElementById('core-filters-per-page-input');
            const p = document.getElementById('core-filters-page-input');
            if (p) p.value = '1';
            if (s) { s.value = $event.target.value; s.dispatchEvent(new Event('change', { bubbles: true })) }
          "}
